using VMLAssembler;

namespace VMLTranslators
{
    /// <summary>
    /// PIC 16F84A 转译器
    /// PIC16 架构：14位指令字，8级深栈，35条指令
    /// 虚拟寄存器映射：
    ///   R0-R7  → PIC 通用寄存器 GPR (0x0C-0x0F 和 0x8C-0x8F)
    ///   R8-R15 → 额外 GPR (0x10-0x17 和 0x90-0x97)
    /// </summary>
    public class TranslatorPIC : Translator8bit
    {
        public override string ARCH_NAME => "PIC";
        protected override string CallMnemonic => "CALL";

        // PIC 中断上下文 (硬件栈仅 8 级深，软中断 helper 内部处理上下文)
        protected override string[] ContextRegNames() => new string[0];
        protected override string NativeIret() => "retfie";
        protected override string NativeCli() => "bcf INTCON, 7";
        protected override string NativeSti() => "bsf INTCON, 7";
        protected override void EmitNativeInt(int vector) => Emit("        call SW_INT");

        // PIC 特殊功能寄存器地址
        private const string INDF = "0x00";
        private const string TMR0 = "0x01";
        private const string PCL = "0x02";
        private const string STATUS = "0x03";
        private const string FSR = "0x04";
        private const string PORTA = "0x05";
        private const string PORTB = "0x06";
        private const string EEDATA = "0x08";
        private const string EEADR = "0x09";
        private const string PCLATH = "0x0A";
        private const string INTCON = "0x0B";
        private const string OPTION_REG = "0x81";
        private const string TRISA = "0x85";
        private const string TRISB = "0x86";
        private const string EECON1 = "0x88";
        private const string EECON2 = "0x89";

        public TranslatorPIC(VmlProgram vmlProgram) : base(vmlProgram) { }

        protected override void EmitHeader()
        {
            Emit("; PIC 16F84A Assembly - Translated from VML");
            Emit("; Generated by VML Translator");
            Emit("; Assembler: gpasm (gputils)");
            Emit("");
            Emit("        processor 16f84a");
            Emit("        radix dec");
            Emit("");
            Emit("        include \"p16f84a.inc\"");
            Emit("");
            Emit("; === Configuration Word ===");
            Emit("        __CONFIG _XT_OSC & _WDT_OFF & _PWRTE_ON & _CP_OFF");
            Emit("");
            Emit("; === Vector Table ===");
            Emit("        org 0x0000");
            Emit("        goto START");
            Emit("");
            Emit("        org 0x0004");
            Emit("        goto ISR");
            Emit("");
        }

        protected override void EmitDataSection()
        {
            if (VmlProgram.DataSection.Count > 0)
            {
                Emit("");
                Emit("; === Data Section ===");
                Emit("        udata");
                foreach (var kvp in VmlProgram.DataSection)
                {
                    string name = kvp.Key;
                    object value = kvp.Value;
                    if (value is string strValue)
                    {
                        Emit($"{name} res 1");
                    }
                    else if (value is System.Collections.IList listValue)
                    {
                        Emit($"{name} res {listValue.Count}");
                    }
                    else if (int.TryParse(value.ToString(), out int intValue))
                    {
                        Emit($"{name} res 1");
                    }
                }
                Emit("");
            }
        }

        protected override void EmitCode()
        {
            Emit("; === Code Section ===");
            Emit("        code");
            Emit("");
            Emit("START:");
            Emit("        banksel TRISB");
            Emit("        clrf TRISB");
            Emit("        banksel PORTB");
            Emit("        clrf PORTB");
            Emit("        movlw 0x00");
            Emit("        movwf STATUS");
            Emit("        goto main");
            Emit("");
            Emit("ISR:");
            Emit("        retfie");
            Emit("");

            foreach (var instr in VmlProgram.Instructions)
            {
                if (!string.IsNullOrEmpty(instr.Label))
                {
                    Emit($"{instr.Label}:");
                }
                NormalizeAndTranslate(instr);
            }
        }

        protected override void TranslateInstruction(Instruction instr)
        {
            // NormalizeBinaryOp handled by BaseTranslator.NormalizeAndTranslate
            // PIC16 是 8 位单 accumulator 架构
            // W = 工作寄存器（累加器），f = 文件寄存器（内存）
            // 指令格式：MOVLW k → LOAD immediate
            //           MOVWF f  → STORE to register
            //           ADDWF f,d → ADD W+f → result to d (W 或 f)
            //           CLRF f   → 寄存器清零

            switch (instr.Opcode)
            {
                                                case OpCode.ADD:
                    TranslateAdd(instr);
                    break;
                case OpCode.SUB:
                    TranslateSub(instr);
                    break;
                case OpCode.MOVE:
                    TranslateMove(instr);
                    break;
                case OpCode.CMP:
                    TranslateCmp(instr);
                    break;
                case OpCode.MUL:
                    Emit("        ; MUL - PIC16 无硬件乘法");
                    Emit("        call MUL8");
                    break;
                case OpCode.DIV:
                    Emit("        ; DIV - PIC16 无硬件除法");
                    Emit("        call DIV8");
                    break;
                case OpCode.MOD:
                    Emit("        ; MOD - PIC16 软实现");
                    Emit("        call MOD8");
                    break;
                case OpCode.AND:
                    Emit($"        movf {GetOperandValue(instr.Operands[1])}, W");
                    Emit($"        andwf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.OR:
                    Emit($"        movf {GetOperandValue(instr.Operands[1])}, W");
                    Emit($"        iorwf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.XOR:
                    Emit($"        movf {GetOperandValue(instr.Operands[1])}, W");
                    Emit($"        xorwf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.NOT:
                    Emit($"        comf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.SHL:
                    Emit($"        bcf STATUS, C");
                    Emit($"        rlf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.SHR:
                    Emit($"        bcf STATUS, C");
                    Emit($"        rrf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.INC:
                    Emit($"        incf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.DEC:
                    Emit($"        decf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.NEG:
                    Emit($"        comf {GetOperandValue(instr.Operands[0])}, W");
                    Emit($"        addlw 1");
                    Emit($"        movwf {GetOperandValue(instr.Operands[0])}");
                    break;
                case OpCode.JMP:
                    Emit($"        goto {instr.Operands[0].Value}");
                    break;
                case OpCode.JZ:
                case OpCode.JE:
                    Emit($"        btfsc STATUS, Z");
                    Emit($"        goto {instr.Operands[0].Value}");
                    break;
                case OpCode.JNZ:
                case OpCode.JNE:
                    Emit($"        btfss STATUS, Z");
                    Emit($"        goto {instr.Operands[0].Value}");
                    break;
                case OpCode.JL:
                    Emit($"        ; JL - 需自定义比较例程");
                    Emit($"        call CMP8");
                    Emit($"        btfsc STATUS, N");
                    Emit($"        goto {instr.Operands[0].Value}");
                    break;
                case OpCode.JLE:
                    Emit($"        call CMP8");
                    Emit($"        btfsc STATUS, Z");
                    Emit($"        goto {instr.Operands[0].Value}");
                    Emit($"        btfsc STATUS, N");
                    Emit($"        goto {instr.Operands[0].Value}");
                    break;
                case OpCode.JG:
                    Emit($"        call CMP8");
                    Emit($"        btfss STATUS, N");
                    Emit($"        btfss STATUS, Z");
                    Emit($"        goto {instr.Operands[0].Value}");
                    break;
                case OpCode.JGE:
                    Emit($"        call CMP8");
                    Emit($"        btfsc STATUS, N");
                    Emit($"        goto {instr.Operands[0].Value}");
                    break;
                case OpCode.HALT:
                    Emit("        sleep");
                    break;
                case OpCode.NOP:
                    Emit("        nop");
                    break;
                case OpCode.STI:
                // CLI/STI/INT/IRET handled by BaseTranslator.TryTranslateCommonOpcode
                case OpCode.THROW:
                    Emit("        call THROW");
                    break;
                case OpCode.CATCH:
                    Emit("        ; CATCH - 设置异常处理标志");
                    break;
                case OpCode.ENDCATCH:
                    break;
                case OpCode.PUSH:
                    Emit($"        movwf TMP");
                    Emit("        swapf STATUS, W");
                    Emit("        push");
                    Emit("        movwf STACK");
                    break;
                case OpCode.POP:
                    Emit("        pop");
                    Emit("        movwf TMP");
                    Emit("        swapf STATUS, F");
                    break;
                case OpCode.CALL:
                    Emit($"        call {instr.Operands[0].Value}");
                    break;
                case OpCode.RET:
                    Emit("        return");
                    break;
                // case OpCode.RET_VAL:
                //     Emit($"        movwf RETVAL");
                //     Emit("        return");
                //     break;
                case OpCode.LABEL:
                    Emit($"{instr.Operands[0].Value}:");
                    break;
                case OpCode.SYSCALL:
                    Emit($"        call __syscall_{instr.Operands[0].Value}");
                    break;

                // 栈帧管理
                case OpCode.ENTER:
                    {
                        int size = int.Parse(instr.Operands[0].Value.ToString());
                        Emit("        ; ENTER - PIC16 用 FSR 做帧指针");
                        Emit("        movf FSR, W");
                        Emit("        movwf _bp_save");
                        if (size > 0)
                            Emit($"        ; SUB SP, {size} - PIC16 无通用栈");
                    }
                    break;
                case OpCode.LEAVE:
                    Emit("        movf _bp_save, W");
                    Emit("        movwf FSR");
                    break;
                case OpCode.CLC:
                    Emit("        bcf STATUS, C");
                    break;
                case OpCode.STC:
                    Emit("        bsf STATUS, C");
                    break;
                                case OpCode.BREAK:
                    Emit("        ; BREAK - PIC16 断点");
                    break;

                // 8位数据传输
                                                                case OpCode.PUSHB:
                    Emit("        ; PUSHB - PIC16 栈用于调用返回");
                    Emit($"        movf {GetOperandValue(instr.Operands[0])}, W");
                    Emit("        movwf _stack_buf");
                    break;
                case OpCode.PUSHH:
                case OpCode.POPB:
                case OpCode.POPH:
                    Emit($"        ; {instr.Opcode} - PIC16 暂不支持");
                    break;

                // 可变移位 / 清零
                case OpCode.SHLV:
                    Emit($"        rlf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.SHRV:
                    Emit($"        rrf {GetOperandValue(instr.Operands[0])}, F");
                    break;
                case OpCode.ZERO:
                    Emit($"        clrf {GetOperandValue(instr.Operands[0])}");
                    break;

                // 内联汇编
                // OpCode.CHIPASM handled by BaseTranslator.TryTranslateCommonOpcode

                case OpCode.FADD:
                case OpCode.FSUB:
                case OpCode.FMUL:
                case OpCode.FDIV:
                case OpCode.FNEG:
                case OpCode.FCMP:
                case OpCode.I2F:
                case OpCode.F2I:
                case OpCode.F2D:
                case OpCode.D2F:
                case OpCode.MOVEF:
                                case OpCode.I2D:
                case OpCode.D2I:
                    Emit($"        call __{instr.Opcode.ToString().ToLower()}");
                    Emit($"        ; {instr.Opcode} - int64/double conversion");
                    break;

                // 内联汇编 (ASM)
                // OpCode.ASM handled by BaseTranslator.TryTranslateCommonOpcode

                // 符号扩展/条件移动/循环移位 (v1.66.28+) — 软件库
                case OpCode.SEXTB: case OpCode.SEXTH:
                case OpCode.CMOVZ: case OpCode.CMOVNZ:
                case OpCode.ROL: case OpCode.ROR:
                    Emit($"        CALL __{instr.Opcode.ToString().ToLower()}");
                    break;

                default:
                    Emit($"        ; UNIMPLEMENTED: {instr.Opcode.ToString()} {string.Join(", ", instr.Operands)}");
                    break;
            }
        }

        private void TranslateLoad(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (src.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src);
                Emit($"        movlw {value}");
                Emit($"        movwf {GetOperandValue(dst)}");
            }
            else if (src.Type == OperandType.MEMORY)
            {
                Emit($"        movf {src.Value}, W");
                Emit($"        movwf {GetOperandValue(dst)}");
            }
            else if (src.Type == OperandType.REGISTER)
            {
                Emit($"        movf {GetOperandValue(src)}, W");
                Emit($"        movwf {GetOperandValue(dst)}");
            }
        }

        private void TranslateStore(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src = instr.Operands[1];

            if (src.Type == OperandType.REGISTER)
            {
                Emit($"        movf {GetOperandValue(src)}, W");
                Emit($"        movwf {GetOperandValue(dst)}");
            }
            else if (src.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src);
                Emit($"        movlw {value}");
                Emit($"        movwf {GetOperandValue(dst)}");
            }
        }

        private void TranslateAdd(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            Emit($"        movf {GetOperandValue(src1)}, W");
            if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        addlw {value}");
            }
            else
            {
                Emit($"        addwf {GetOperandValue(src2)}, W");
            }
            Emit($"        movwf {GetOperandValue(dst)}");
        }

        private void TranslateSub(Instruction instr)
        {
            var dst = instr.Operands[0];
            var src1 = instr.Operands[1];
            var src2 = instr.Operands[2];

            Emit($"        movf {GetOperandValue(src1)}, W");
            if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        sublw {value}");
            }
            else
            {
                Emit($"        subwf {GetOperandValue(src2)}, W");
            }
            Emit($"        movwf {GetOperandValue(dst)}");
        }

        private void TranslateMove(Instruction instr)
        {
            // v1.65.167+: 统一 MOVE — MEM/LABEL dest → Store, 其他 → Load
            if (instr.Operands[0].Type == OperandType.MEMORY ||
                instr.Operands[0].Type == OperandType.INDIRECT ||
                instr.Operands[0].Type == OperandType.LABEL)
            {
                TranslateStore(instr);
                return;
            }
            TranslateLoad(instr);
        }

        private void TranslateCmp(Instruction instr)
        {
            var src1 = instr.Operands[0];
            var src2 = instr.Operands[1];
            Emit($"        movf {GetOperandValue(src1)}, W");
            if (src2.Type == OperandType.IMMEDIATE)
            {
                int value = SafeToInt(src2);
                Emit($"        sublw {value}");
            }
            else
            {
                Emit($"        subwf {GetOperandValue(src2)}, W");
            }
        }

        protected override string MapRegister(int regNum)
        {
            // 虚拟寄存器 R0-R7 → GPR 0x0C-0x0F
            // 虚拟寄存器 R8-R15 → GPR 0x10-0x17
            if (regNum < 0) return "0x0C";
            int addr = regNum < 8 ? 0x0C + regNum : 0x10 + (regNum - 8);
            return $"0x{addr:X2}";
        }
    }
}
